from collections import Counter, defaultdict
from random import Random
from vs import corpus, ivtff
import json

def mode(counts):
    return min(counts,key=lambda ch: (-counts[ch],ch))

def score(train,test):
    unigrams=Counter(c for w in train for c in w)
    pairs=defaultdict(Counter)
    for word in train:
        for i,c in enumerate(word):
            pairs[word[i-1] if i else "^"][c]+=1
    global_guess=mode(unigrams)
    guesses={prefix:mode(counts) for prefix,counts in pairs.items()}
    den=sum(map(len,test))
    return [sum(c==global_guess for w in test for c in w)/den,
            sum(c==guesses.get(w[i-1] if i else "^",global_guess)
                for w in test for i,c in enumerate(w))/den]

def shuffle(words, rng, preserve_edges):
    result=[]
    for word in words:
        if preserve_edges and len(word)<=2:
            result.append(word)
            continue
        chars=list(word[1:-1] if preserve_edges else word)
        rng.shuffle(chars)
        middle="".join(chars)
        result.append(word[0]+middle+word[-1] if preserve_edges else middle)
    return result

results={}
for edition in ("zl","it"):
    fit,practice=corpus.split_pages("practice",edition)
    def types(pages):
        return {w for p in pages if p.language=="B" for l in p.lines if l.unit=="P"
                for w in l.words if set(w)<=set("acdefghiklmnopqrsty") and not ivtff.uncertain(w)}
    train=sorted(types(fit))
    test=sorted(types(practice)-set(train))
    conditions={}
    for name,edges in (("shuffle_all",False),("preserve_edges",True)):
        conditions[name]=[]
        for i in range(16):
            rng=Random(300+i)
            conditions[name].append(score(shuffle(train,rng,edges),shuffle(test,rng,edges)))
    results[edition]=dict(train=len(train),test=len(test),observed=score(train,test),controls=conditions)
print(json.dumps(results,indent=2))
